func StreamStrings(prefix string, n int) (<-chan string, <-chan error) {
  ch := make(chan string)
  errc := make(chan error, 1)
  // set up cgo.Handle for ctx, call C.stream_strings with bridge_cb and ctx
  // close channels when done
  return ch, errc
}
```

